import pandas as pd, numpy as np
from pymatgen.io.vasp import Poscar
from pymatgen.analysis.structure_matcher import StructureMatcher
from collections import Counter
tr=pd.read_csv('nlo_shg_train.csv'); po=pd.read_csv('nlo_pool.csv')
ts=[Poscar.from_str(x).structure for x in tr.poscar]; ps=[Poscar.from_str(x).structure for x in po.poscar]
def sig(s):
 vals=np.array(list(s.composition.get_el_amt_dict().values()),float)
 vals/=vals.min()
 return (len(vals), tuple(np.round(sorted(vals),5)))
sm=StructureMatcher(ltol=.25,stol=.3,angle_tol=5,primitive_cell=True,scale=True,attempt_supercell=True)
for j,p in enumerate(ps):
 vals=[]
 for i,t in enumerate(ts):
  if sig(p)!=sig(t): continue
  try:
   r=sm.get_rms_anonymous(p,t)
  except Exception: r=None
  if r is not None: vals.append((r[0],r[1],i))
 vals.sort()
 if vals:
  out=[]
  for _,_,i in vals[:4]: out.append(f'{tr.formula[i]}:{tr.shg[i]:.1f}')
  print(po.candidate_id[j],po.formula[j], ' | '.join(out), 'rms',','.join(f'{x[0]:.3f}' for x in vals[:4]))
PY

